// Process sentiment data and detect shifts
const items = [];

// Get aggregate sentiment
const agg = $('Get Aggregate Sentiment').first().json;
const newsData = $('Fetch Crypto+Fed News').first().json;
const redditCrypto = $('Fetch Reddit Crypto').first().json;
const redditWSB = $('Fetch Reddit WSB').first().json;

// Calculate sentiment scores
const newsSentiment = newsData?.average_sentiment || 0;
const cryptoSentiment = redditCrypto?.average_sentiment || 0;
const wsbSentiment = redditWSB?.average_sentiment || 0;
const overallSentiment = (newsSentiment + cryptoSentiment + wsbSentiment) / 3;

// Determine sentiment regime
let regime = 'NEUTRAL';
let regimeColor = '🟡';
if (overallSentiment > 0.3) { regime = 'BULLISH'; regimeColor = '🟢'; }
else if (overallSentiment < -0.3) { regime = 'BEARISH'; regimeColor = '🔴'; }

// Extract top stories
const topStories = (newsData?.results || []).slice(0, 5).map(r => ({
  title: r.title,
  sentiment: r.sentiment,
  source: r.source
}));

// Extract top reddit posts
const topReddit = (redditCrypto?.results || []).slice(0, 5).map(r => ({
  title: r.title,
  sentiment: r.sentiment,
  score: r.score
}));

// Build summary
const summary = `${regimeColor} OSINT: ${regime} (${overallSentiment.toFixed(2)})\n` +
  `News: ${newsSentiment.toFixed(2)} (${newsData?.count || 0} articles)\n` +
  `Reddit: Crypto ${cryptoSentiment.toFixed(2)}, WSB ${wsbSentiment.toFixed(2)}\n` +
  `Top: ${topStories[0]?.title?.substring(0, 80) || 'N/A'}`;

// Build CB v1 envelope for significant sentiment
const isSignificant = Math.abs(overallSentiment) > 0.2 || Math.abs(newsSentiment) > 0.4;

items.push({
  json: {
    timestamp: new Date().toISOString(),
    source: 'k9-osint-n8n',
    type: 'sentiment_snapshot',
    ontology_tags: ['sentiment', 'osint', 'news', 'reddit'],
    confidence: isSignificant ? 0.82 : 0.5,
    payload: {
      regime,
      overall_sentiment: overallSentiment,
      news_sentiment: newsSentiment,
      reddit_crypto_sentiment: cryptoSentiment,
      reddit_wsb_sentiment: wsbSentiment,
      news_count: newsData?.count || 0,
      reddit_count: (redditCrypto?.count || 0) + (redditWSB?.count || 0),
      top_stories: topStories,
      top_reddit: topReddit,
      summary
    },
    is_significant: isSignificant,
    trace_id: '',
    causation_id: '',
    signature: ''
  }
});

return items;
